node -e "
const fs = require('fs');
const html = fs.readFileSync('index.html','utf8');
const src = fs.readFileSync('app.js','utf8');
// minimal DOM stub
const listeners = {};
const el = { textContent: 'idle' };
global.document = {
  getElementById: (id) => (id === 'state' ? el : null),
  addEventListener: (type, fn) => { (listeners[type] = listeners[type] || []).push(fn); },
};
eval(src);
const fire = (key) => listeners.keydown.forEach(fn => fn({ key }));
fire('ArrowLeft');
console.log('after ArrowLeft:', el.textContent);
fire('ArrowRight');
console.log('after ArrowRight:', el.textContent);
fire('a');
console.log('after a:', el.textContent);
"

